const DICIONARIOS = { pt, en, es };

// ------------------------------------------------------------------- estado

/**
 * Idioma inicial: o que o jogador escolheu, senão o do navegador, senão PT.
 *
 * `navigator.language` vem como "pt-BR", "en-US", "es-419" — o prefixo basta.
 */
function idiomaInicial() {
  // Fora do browser (o teste de cobertura importa este módulo em Node) não há localStorage
  // nem navigator — cair no padrão é o certo, e é melhor do que exigir um DOM de mentira só
  // para conseguir ler o dicionário.
  if (typeof localStorage === 'undefined') return PADRAO;
  const salvo = localStorage.getItem('idioma');
  if (idiomaValido(salvo)) return salvo;
  const doNavegador = (globalThis.navigator?.language ?? '').slice(0, 2).toLowerCase();
  return idiomaValido(doNavegador) ? doNavegador : PADRAO;
}

let atual = idiomaInicial();

export const idioma = () => atual;

const faltando = new Set();

/**
 * A frase, no idioma atual, com `{chaves}` trocadas por `params`.
 *
 * Os valores são inseridos como estão: várias frases do dicionário trazem `<b>`/`<span>` e
 * são jogadas na tela com `innerHTML`. Quem interpolar texto de JOGADOR (nick, mensagem de
 * chat) tem de passar por `escapar()` ANTES — o `t()` não tem como saber a diferença.
 */
export function t(chave, params) {
  let frase = DICIONARIOS[atual]?.[chave];
  if (frase === undefined) {
    frase = DICIONARIOS[PADRAO][chave];
    if (frase === undefined) {
      if (!faltando.has(chave)) {
        faltando.add(chave);
        console.warn(`[i18n] chave sem tradução: ${chave}`);
      }
      return chave;
    }
  }
  if (!params) return frase;
  return frase.replace(/\{(\w+)\}/g, (todo, k) => (params[k] !== undefined ? String(params[k]) : todo));
}

/**
 * Esta chave existe no dicionário?
 *
 * Serve a quem tem um texto ALTERNATIVO para mostrar quando não existe — hoje a vitrine da
 * Loja, cujo catálogo é montado no servidor e chega com a frase já pronta em português. Sem
 * isto, `t()` devolveria a própria chave (`loja.d.beast` na tela) em vez de cair no texto do
 * servidor, e um produto novo lá que ainda não tivesse tradução apareceria quebrado.
 *
 * Pergunta ao dicionário PADRÃO de propósito: uma chave que existe em português e ainda não
 * foi traduzida vale como existente — o `t()` já sabe cair no português nesse caso, e isso é
 * melhor do que a frase crua do servidor.
 */
export const temChave = (chave) => DICIONARIOS[PADRAO][chave] !== undefined;

/** Troca o idioma, grava a escolha e redesenha a tela. */
export function trocarIdioma(id, aoTrocar) {
  if (!idiomaValido(id) || id === atual) return false;
  atual = id;
  localStorage.setItem('idioma', id);
  aplicarI18n();
  aoTrocar?.(id);
  return true;
}

/**
 * Percorre o documento e traduz tudo que está marcado.
 *
 *   data-i18n="chave"                       → textContent
 *   data-i18n-html="chave"                  → innerHTML (para frases com <b>)
 *   data-i18n-attr="placeholder:chave;title:outra"  → atributos
 *
 * Roda no boot e a cada troca de idioma. É idempotente de propósito: o conteúdo escrito no
 * HTML é só o padrão, e sobrescrever de novo com a mesma chave não faz diferença.
 */
export function aplicarI18n(raiz = document) {
  for (const el of raiz.querySelectorAll('[data-i18n]')) el.textContent = t(el.dataset.i18n);
  for (const el of raiz.querySelectorAll('[data-i18n-html]')) el.innerHTML = t(el.dataset.i18nHtml);
  for (const el of raiz.querySelectorAll('[data-i18n-attr]')) {
    for (const par of el.dataset.i18nAttr.split(';')) {
      const [attr, chave] = par.split(':').map((s) => s.trim());
      if (attr && chave) el.setAttribute(attr, t(chave));
    }
  }
  const lang = IDIOMAS.find((l) => l.id === atual);
  if (lang) document.documentElement.lang = lang.htmlLang;
  document.title = t('doc.titulo');
}

/**
 * As bandeiras de idioma da UI e a caixa que recebe sair + redes.
 *
 * Fica no `body` de propósito — dentro de `.col.esq` (overflow auto/hidden) um filho
 * `position: fixed` é recortado e some. O CSS fixa no canto inferior esquerdo.
 */
export function montarSeletorDeIdioma(aoTrocar) {
  const caixa = document.createElement('div');
  caixa.className = 'idiomas';
  caixa.title = t('tip.idioma');

  for (const l of IDIOMAS) {
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'idioma-btn' + (l.id === atual ? ' on' : '');
    b.dataset.idioma = l.id;
    b.title = l.nome;
    b.setAttribute('aria-label', l.nome);
    b.innerHTML = l.bandeira;
    b.onclick = () => {
      if (!trocarIdioma(l.id, aoTrocar)) return;
      // Só as BANDEIRAS: a caixa tem outros moradores (o botão de sair, que o app pendura
      // aqui), e varrer `children` apagaria o estado deles junto.
      for (const outro of caixa.querySelectorAll('.idioma-btn')) {
        outro.classList.toggle('on', outro.dataset.idioma === l.id);
      }
      caixa.title = t('tip.idioma');
    };
    caixa.appendChild(b);
  }
  document.body.appendChild(caixa);
  return caixa;
}

/** Conferência de cobertura: usada pelo teste, não pelo jogo. */
export const _dicionarios = DICIONARIOS;
